const body = $json.body || {};
const details = body.details || {};

const laborHours = Number(details.labor_hours || 8);
const fairWageEarned = laborHours * 120.0; // ₹120/hr statutory floor

return [{
  json: {
    timestamp: new Date().toISOString(),
    event: body.event || 'EVENT_LOG',
    ministry: body.ministry || 'Ministry of Social Justice & Empowerment',
    beneficiary_collective: body.beneficiary_collective || 'NBCFDC & NSFDC',
    item_id: details.item_id || 'UNKNOWN',
    item_title: details.title || 'Handicraft Item',
    craft_category: details.category || 'Handicrafts',
    cluster_pin: details.cluster_pin || '273001',
    b2c_price: details.b2c_price || 0.0,
    labor_hours_protected: laborHours,
    statutory_living_wage_inr: fairWageEarned
  }
}];
